<template><main class="journey-detail"><a-spin :spinning="loading"><template v-if="journey"><header><NuxtLink to="/journeys"><Icon name="ph:arrow-left-bold" />旅行</NuxtLink><h1>{{ journey.title }}</h1><p>{{ journey.description }}</p></header><JourneyMap :stops="journey.stops" /><section class="stops"><article v-for="(stop,index) in journey.stops" :key="stop.id"><span>{{ String(index+1).padStart(2,'0') }}</span><div><small>{{ formatDate(stop.occurredAt) }}<template v-if="stop.publicLocation"> · {{ stop.publicLocation.name }}</template></small><h2>{{ stop.title }}</h2><p>{{ stop.narration }}</p></div></article></section></template><a-empty v-else-if="!loading" description="旅行不存在" /></a-spin></main></template>
<script setup lang="ts">const api=useApi();const route=useRoute();const loading=ref(true);const journey=ref<any>();onMounted(async()=>{try{journey.value=await api.get(`/journeys/${route.params.slug}`)}catch{journey.value=null}finally{loading.value=false}});function formatDate(v:string){return v?new Date(v).toLocaleDateString('zh-CN'):''}useHead(()=>({title:journey.value?.title||'旅行'}))</script>
<style scoped>.journey-detail{width:min(1050px,calc(100% - 32px));margin:0 auto;padding:38px 0 90px}.journey-detail header{max-width:720px;margin-bottom:28px}.journey-detail header a{display:inline-flex;align-items:center;gap:5px;color:var(--c-text-3);font-size:.72rem;text-decoration:none}.journey-detail h1{margin:18px 0 10px;color:var(--c-text);font-size:2.3rem}.journey-detail header p{color:var(--c-text-2);line-height:1.8}.stops{margin:42px auto 0;max-width:760px}.stops article{display:grid;grid-template-columns:54px 1fr;gap:18px;padding:0 0 34px}.stops article>span{display:grid;width:42px;height:42px;border:1px solid var(--c-primary);border-radius:50%;color:var(--c-primary);font:700 .72rem var(--font-accent);place-items:center}.stops article div{padding-bottom:28px;border-bottom:1px solid var(--border)}.stops small{color:var(--c-text-3)}.stops h2{margin:7px 0;color:var(--c-text);font-size:1.1rem}.stops p{margin:0;color:var(--c-text-2);line-height:1.8}</style>
